test('SourceSwitch - matchBestChapter - exact title matches', () => {
  const chapters: Chapter[] = [
    { index: 0, title: '第一章 穿越异界', url: 'http://example.com/1' },
    { index: 1, title: '第二章 绝世神功', url: 'http://example.com/2' },
    { index: 2, title: '第三章 家族大比', url: 'http://example.com/3' },
  ]

  const matched = matchBestChapter(chapters, '第二章 绝世神功', 0)
  assert.equal(matched.index, 1)
  assert.equal(matched.title, '第二章 绝世神功')
})

test('SourceSwitch - matchBestChapter - normalized title matching (different chapter format)', () => {
  const chapters: Chapter[] = [
    { index: 0, title: '第1章 穿越异界！', url: 'http://example.com/1' },
    { index: 1, title: '第2章 绝世神功（修）', url: 'http://example.com/2' },
    { index: 2, title: '第3章 家族大比', url: 'http://example.com/3' },
  ]

  // Search with "第二章 绝世神功" should match "第2章 绝世神功（修）" via normalized clean matching
  const matched = matchBestChapter(chapters, '第二章 绝世神功', 0)
  assert.equal(matched.index, 1)
  assert.equal(matched.title, '第2章 绝世神功（修）')
})

test('SourceSwitch - matchBestChapter - fallback to index when title is completely different', () => {
  const chapters: Chapter[] = [
    { index: 0, title: '序章', url: 'http://example.com/0' },
    { index: 1, title: '开启', url: 'http://example.com/1' },
    { index: 2, title: '终曲', url: 'http://example.com/2' },
  ]

  const matched = matchBestChapter(chapters, '第九十九回 飞升大结局', 2)
  assert.equal(matched.index, 2)
  assert.equal(matched.title, '终曲')
})

test('SourceSwitch - matchBestChapter - clamping when target index exceeds chapters length', () => {
  const chapters: Chapter[] = [
    { index: 0, title: '单章', url: 'http://example.com/0' },
  ]

  const matched = matchBestChapter(chapters, '第五十章', 50)
  assert.equal(matched.index, 0)
  assert.equal(matched.title, '单章')
})

test('Toast - pub/sub event lifecycle and id generation', () => {
  let currentList: any[] = []
  const unsubscribe = toast.subscribe(toasts => {
    currentList = toasts
  })

  const id1 = toast.success('缓存完成', 0)
  const id2 = toast.error('网络错误', 0)
  const id3 = toast.warning('书源已失效', 0)
  const id4 = toast.info('正在搜索', 0)

  assert.equal(currentList.length, 4)
  assert.equal(currentList[0].id, id1)
  assert.equal(currentList[0].type, 'success')
  assert.equal(currentList[0].message, '缓存完成')
  assert.equal(currentList[1].id, id2)
  assert.equal(currentList[1].type, 'error')
  assert.equal(currentList[2].id, id3)
  assert.equal(currentList[2].type, 'warning')
  assert.equal(currentList[3].id, id4)
  assert.equal(currentList[3].type, 'info')

  toast.dismiss(id1)
  assert.equal(currentList.length, 3)
  assert.equal(currentList[0].id, id2)

  unsubscribe()
  toast.info('Should not update currentList after unsubscribe', 0)
  assert.equal(currentList.length, 3)
})

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { api, Chapter, SearchResult, SearchStreamEvent, streamSearch } from './api'
import { Icon } from './icons'
import { toast } from './Toast'

export type SourceCandidate = {
  result: SearchResult
  isKnownAlternate?: boolean
  isCurrent?: boolean
  status: 'idle' | 'loading' | 'loaded' | 'error'
  latestChapter?: string
  totalChapters?: number
  matchedChapterIndex?: number
  matchedChapterTitle?: string
  chapters?: Chapter[]
  error?: string
}

export type SourceSwitchModalProps = {
  bookName: string
  author?: string
  currentSourceId: string
  currentBookUrl: string
  currentChapterTitle?: string
  currentChapterIndex?: number
  knownAlternateSources?: SearchResult[]
  onSwitch: (chosen: { result: SearchResult; chapters: Chapter[]; targetChapterIndex: number }) => Promise<void>
  onClose: () => void
}

const normalizeTitle = (title: string): string =>
  title
    .replace(/^第[0-9一二三四五六七八九十百千万]+[章回节集卷]\s*/gu, '')
    .replace(/^chapter\s*[0-9]+/iu, '')
    .replace(/[\s\p{P}\p{S}]/gu, '')
    .toLowerCase()

export function matchBestChapter(
  chapters: Chapter[],
  currentTitle?: string,
  currentIndex?: number
): { index: number; title: string } {
  if (chapters.length === 0) return { index: 0, title: '' }

  if (currentTitle) {
    const normCurrent = normalizeTitle(currentTitle)
    if (normCurrent.length >= 2) {
      // 1. Exact match on raw title
      const exact = chapters.find(c => c.title.trim() === currentTitle.trim())
      if (exact) return { index: exact.index, title: exact.title }

      // 2. Exact match on normalized title
      const normExact = chapters.find(c => normalizeTitle(c.title) === normCurrent)
      if (normExact) return { index: normExact.index, title: normExact.title }

      // 3. Substring inclusion
      const substr = chapters.find(c => {
        const norm = normalizeTitle(c.title)
        return norm.length >= 2 && (norm.includes(normCurrent) || normCurrent.includes(norm))
      })
      if (substr) return { index: substr.index, title: substr.title }
    }
  }

  // Fallback to index
  const safeIdx = Math.min(Math.max(0, currentIndex ?? 0), chapters.length - 1)
  return { index: safeIdx, title: chapters[safeIdx]?.title || '' }
}

export function SourceSwitchModal({
  bookName,
  author,
  currentSourceId,
  currentBookUrl,
  currentChapterTitle,
  currentChapterIndex,
  knownAlternateSources = [],
  onSwitch,
  onClose,
}: SourceSwitchModalProps) {
  const [candidates, setCandidates] = useState<SourceCandidate[]>([])
  const [searchProgress, setSearchProgress] = useState<SearchStreamEvent | null>(null)
  const [searching, setSearching] = useState(true)
  const [switchingSourceId, setSwitchingSourceId] = useState<string | null>(null)

  const socketRef = useRef<WebSocket | null>(null)
  const fetchingTocRef = useRef<Set<string>>(new Set())

  const fetchCandidateToc = useCallback(async (candidate: SourceCandidate) => {
    const key = `${candidate.result.sourceId}\u0000${candidate.result.bookUrl}`
    if (fetchingTocRef.current.has(key)) return
    fetchingTocRef.current.add(key)

    setCandidates(prev =>
      prev.map(c =>
        c.result.sourceId === candidate.result.sourceId && c.result.bookUrl === candidate.result.bookUrl
          ? { ...c, status: 'loading', error: undefined }
          : c
      )
    )

    try {
      const details = await api.details(candidate.result.sourceId, candidate.result.bookUrl)
      const chapters = await api.chapters(candidate.result.sourceId, details.tocUrl)
      const latest = chapters.at(-1)?.title
      const best = matchBestChapter(chapters, currentChapterTitle, currentChapterIndex)

      setCandidates(prev =>
        prev.map(c =>
          c.result.sourceId === candidate.result.sourceId && c.result.bookUrl === candidate.result.bookUrl
            ? {
                ...c,
                status: 'loaded',
                chapters,
                totalChapters: chapters.length,
                latestChapter: latest,
                matchedChapterIndex: best.index,
                matchedChapterTitle: best.title,
              }
            : c
        )
      )
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : '无法获取目录'
      setCandidates(prev =>
        prev.map(c =>
          c.result.sourceId === candidate.result.sourceId && c.result.bookUrl === candidate.result.bookUrl
            ? { ...c, status: 'error', error: errorMsg }
            : c
        )
      )
    } finally {
      fetchingTocRef.current.delete(key)
    }
  }, [currentChapterIndex, currentChapterTitle])

  // Initialize known alternates
  useEffect(() => {
    const initialList: SourceCandidate[] = []

    // 1. Current source (if available)
    initialList.push({
      result: {
        sourceId: currentSourceId,
        bookUrl: currentBookUrl,
        name: bookName,
        author,
      },
      isCurrent: true,
      status: 'idle',
    })

    // 2. Known alternate sources
    for (const alt of knownAlternateSources) {
      if (alt.sourceId === currentSourceId && alt.bookUrl === currentBookUrl) continue
      initialList.push({
        result: alt,
        isKnownAlternate: true,
        status: 'idle',
      })
    }

    setCandidates(initialList)

    // Trigger TOC fetch for known alternates
    initialList.forEach(cand => {
      if (!cand.isCurrent) {
        void fetchCandidateToc(cand)
      }
    })
  }, [author, bookName, currentBookUrl, currentSourceId, fetchCandidateToc, knownAlternateSources])

  // Start streaming search for other sources
  useEffect(() => {
    let cancelled = false
    setSearching(true)

    const socket = streamSearch(
      bookName,
      undefined,
      event => {
        if (cancelled) return
        if (event.type === 'start' || event.type === 'progress' || event.type === 'done') {
          setSearchProgress(event)
        }
        if (event.type === 'results' && event.results.length > 0) {
          setCandidates(prev => {
            const existingKeys = new Set(prev.map(c => `${c.result.sourceId}\u0000${c.result.bookUrl}`))
            const newCandidates: SourceCandidate[] = []

            for (const r of event.results) {
              const key = `${r.sourceId}\u0000${r.bookUrl}`
              // Filter by book name similarity
              if (
                !existingKeys.has(key) &&
                r.name.trim().toLowerCase() === bookName.trim().toLowerCase()
              ) {
                existingKeys.add(key)
                const candidate: SourceCandidate = {
                  result: r,
                  status: 'idle',
                }
                newCandidates.push(candidate)
                // Automatically fetch TOC for newly found candidates
                void fetchCandidateToc(candidate)
              }
            }

            return newCandidates.length > 0 ? [...prev, ...newCandidates] : prev
          })
        }
        if (event.type === 'done' || event.type === 'error') {
          setSearching(false)
        }
      },
      () => {
        if (!cancelled) setSearching(false)
      },
      () => {
        if (!cancelled) setSearching(false)
      }
    )

    socketRef.current = socket

    return () => {
      cancelled = true
      socketRef.current?.close()
      socketRef.current = null
    }
  }, [bookName, fetchCandidateToc])

  const handleSelect = async (candidate: SourceCandidate) => {
    if (candidate.isCurrent) {
      toast.info('当前已是该书源')
      return
    }

    setSwitchingSourceId(candidate.result.sourceId)

    try {
      let chapters = candidate.chapters
      let targetIndex = candidate.matchedChapterIndex ?? 0

      if (!chapters) {
        const details = await api.details(candidate.result.sourceId, candidate.result.bookUrl)
        chapters = await api.chapters(candidate.result.sourceId, details.tocUrl)
        const best = matchBestChapter(chapters, currentChapterTitle, currentChapterIndex)
        targetIndex = best.index
      }

      await onSwitch({
        result: candidate.result,
        chapters,
        targetChapterIndex: targetIndex,
      })

      const targetTitle = chapters[targetIndex]?.title || `第 ${targetIndex + 1} 章`
      toast.success(`已切换至【${candidate.result.sourceId}】，定位至：${targetTitle}`)
      onClose()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : '切换书源失败')
    } finally {
      setSwitchingSourceId(null)
    }
  }

  const sortedCandidates = useMemo(() => {
    return [...candidates].sort((a, b) => {
      // 1. Current source first
      if (a.isCurrent) return -1
      if (b.isCurrent) return 1
      // 2. Known alternate sources second
      if (a.isKnownAlternate && !b.isKnownAlternate) return -1
      if (!a.isKnownAlternate && b.isKnownAlternate) return 1
      // 3. Loaded sources with more chapters first
      if (a.status === 'loaded' && b.status !== 'loaded') return -1
      if (a.status !== 'loaded' && b.status === 'loaded') return 1
      if (a.totalChapters && b.totalChapters) return b.totalChapters - a.totalChapters
      return 0
    })
  }, [candidates])

  const progressPercent = searchProgress?.totalSources
    ? Math.round((searchProgress.completedSources / searchProgress.totalSources) * 100)
    : 0

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div
        className="source-switch-dialog"
        onClick={e => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label={`切换书源: ${bookName}`}
      >
        <header className="source-switch-header">
          <div>
            <div className="source-switch-kicker">
              <Icon name="sliders" />
              <span>切换书源</span>
            </div>
            <h2>{bookName}</h2>
            <small>{author ? `作者: ${author}` : '未知作者'} · 当前：{currentSourceId}</small>
          </div>
          <button className="subtle-button close-btn" onClick={onClose} aria-label="关闭">
            <Icon name="close" />
          </button>
        </header>

        {/* Search Stream Progress Banner */}
        <div className="source-search-banner">
          <div className="search-banner-text">
            <span>
              {searching ? (
                <>正在全源检索《{bookName}》...</>
              ) : (
                <>全源检索完成，共找到 {candidates.length} 个书源</>
              )}
            </span>
            <small>
              {searchProgress
                ? `已扫描 ${searchProgress.completedSources} / ${searchProgress.totalSources} 个书源`
                : '准备检索...'}
            </small>
          </div>
          {searching && (
            <div className="search-progress-bar-track">
              <div
                className="search-progress-bar-fill"
                style={{ width: `${Math.max(5, progressPercent)}%` }}
              />
            </div>
          )}
        </div>

        {/* Candidate List */}
        <div className="source-candidate-list">
          {sortedCandidates.map(c => {
            const isSwitching = switchingSourceId === c.result.sourceId
            const isLoading = c.status === 'loading'
            const isError = c.status === 'error'
            const isCurrent = c.isCurrent

            let metaText = '点击拉取目录并切换'
            if (isCurrent) {
              metaText = '当前正在阅读的书源'
            } else if (isLoading) {
              metaText = '正在提取目录与章节...'
            } else if (isError) {
              metaText = c.error || '获取目录失败'
            } else if (c.status === 'loaded') {
              metaText = `共 ${c.totalChapters ?? 0} 章 · 最新：${c.latestChapter || '无'}`
            }

            return (
              <article
                key={`${c.result.sourceId}-${c.result.bookUrl}`}
                className={`source-candidate-card ${isCurrent ? 'current' : ''} ${isError ? 'error' : ''}`}
              >
                <div className="candidate-main">
                  <div className="candidate-title-row">
                    <strong>{c.result.sourceId}</strong>
                    {isCurrent && <span className="source-badge current">当前书源</span>}
                    {c.isKnownAlternate && !isCurrent && (
                      <span className="source-badge alternate">已收录候选</span>
                    )}
                  </div>
                  <p className="candidate-meta">{metaText}</p>
                  {c.matchedChapterTitle && !isCurrent && (
                    <small className="candidate-match">
                      智能定位至：第 {(c.matchedChapterIndex ?? 0) + 1} 章 · {c.matchedChapterTitle}
                    </small>
                  )}
                </div>

                <div className="candidate-action">
                  {isCurrent ? (
                    <span className="current-indicator">使用中</span>
                  ) : (
                    <button
                      className="primary-button switch-btn"
                      disabled={isSwitching}
                      onClick={() => void handleSelect(c)}
                    >
                      {isSwitching ? '切换中...' : '切换'}
                    </button>
                  )}
                </div>
              </article>
            )
          })}

          {sortedCandidates.length === 0 && !searching && (
            <div className="source-switch-empty">
              <Icon name="book" />
              <p>未在其他书源中发现匹配的《{bookName}》</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export type SourceSummary = { id: string; name: string; url: string; group?: string; enabled: boolean; isJsSource: boolean; updatedAt: number; version: number }
export type SourceRecord = { id: string; json: string; version: number; updatedAt: number }
export type SearchResult = { sourceId: string; name: string; author?: string; bookUrl: string; coverUrl?: string; intro?: string }
export type BookDetails = { sourceId: string; name: string; author?: string; intro?: string; coverUrl?: string; tocUrl: string; alternateSources?: SearchResult[] }
export type Chapter = { index: number; title: string; url: string }
export type ReadingProgress = { sourceId: string; bookUrl: string; chapterUrl: string; chapterIndex: number; scrollPosition: number; updatedAt: number }
export type BookshelfItem = { sourceId: string; bookUrl: string; name: string; author?: string; tocUrl: string; coverKey?: string; chapterIndex?: number; scrollPosition?: number; lastReadAt: number; cachedChapters: number; totalChapters: number; cacheState: 'idle' | 'caching' | 'ready' | 'failed'; cacheError?: string; completed: boolean; alternateSources?: SearchResult[] }
export type BookshelfWrite = { sourceId: string; bookUrl: string; name: string; author?: string; tocUrl: string; coverUrl?: string; alternateSources?: SearchResult[] }
export type BookshelfSourceSwitch = { oldSourceId: string; oldBookUrl: string; book: BookshelfWrite; alternateSources?: SearchResult[] }
export type ImportResponse = { imported: number; updated: number; skipped: number; errors: string[] }
export type SourceSubscription = { id: number; url: string; enabled: boolean; createdAt: number; updatedAt: number; lastSuccessAt?: number; lastAttemptAt?: number; lastError?: string; lastImported: number; contentHash?: string }
export type SearchStreamEvent = { type: 'start' | 'results' | 'progress' | 'done' | 'error'; totalSources: number; completedSources: number; matchedSources: number; emptySources: number; failedSources: number; resultCount: number; results: SearchResult[]; message?: string }

let csrfToken: string | null = null
export const setCsrfToken = (token: string | null) => { csrfToken = token }

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers)
  if (init.body) headers.set('Content-Type', 'application/json')
  if (init.method && !['GET', 'HEAD'].includes(init.method)) headers.set('X-CSRF-Token', csrfToken ?? '')
  const response = await fetch(path, { ...init, headers, credentials: 'same-origin' })
  if (!response.ok) {
    const body = await response.json().catch(() => ({ message: response.statusText })) as { message?: string }
    throw new Error(body.message ?? '请求失败')
  }
  return response.status === 204 ? undefined as T : response.json() as Promise<T>
}

export const api = {
  session: () => request<{ authenticated: boolean; csrfToken?: string }>('/api/auth/session'),
  login: (password: string) => request<{ csrfToken: string }>('/api/auth/login', { method: 'POST', body: JSON.stringify({ password }) }),
  logout: () => request<void>('/api/auth/logout', { method: 'POST' }),
  sources: (query = '') => request<SourceSummary[]>(`/api/sources?q=${encodeURIComponent(query)}`),
  source: (id: string) => request<SourceRecord>(`/api/sources/${encodeURIComponent(id)}`),
  save: (id: string, json: string, version?: number) => request<SourceRecord>(`/api/sources/${encodeURIComponent(id)}`, { method: 'PUT', body: JSON.stringify({ json, version }) }),
  remove: (id: string) => request<void>(`/api/sources/${encodeURIComponent(id)}`, { method: 'DELETE' }),
  validate: (id: string) => request<{ valid: boolean; errors: string[]; warnings: string[] }>(`/api/sources/${encodeURIComponent(id)}/validate`, { method: 'POST' }),
  import: (sources: string[]) => request<ImportResponse>('/api/sources/import', { method: 'POST', body: JSON.stringify({ sources }) }),
  subscriptions: () => request<SourceSubscription[]>('/api/subscriptions'),
  saveSubscription: (url: string, enabled = true) => request<SourceSubscription>('/api/subscriptions', { method: 'POST', body: JSON.stringify({ url, enabled }) }),
  removeSubscription: (id: number) => request<void>(`/api/subscriptions/${id}`, { method: 'DELETE' }),
  updateSubscription: (id: number) => request<ImportResponse>(`/api/subscriptions/${id}/update`, { method: 'POST' }),
  updateSubscriptions: () => request<{ updated: number; failed: number }>('/api/subscriptions/update', { method: 'POST' }),
  search: (keyword: string, sourceIds?: string[]) => request<SearchResult[]>('/api/search', { method: 'POST', body: JSON.stringify({ keyword, sourceIds }) }),
  details: (sourceId: string, bookUrl: string) => request<BookDetails>('/api/books/details', { method: 'POST', body: JSON.stringify({ sourceId, bookUrl }) }),
  chapters: (sourceId: string, bookUrl: string) => request<Chapter[]>('/api/books/chapters', { method: 'POST', body: JSON.stringify({ sourceId, bookUrl }) }),
  content: (sourceId: string, chapterUrl: string, bookUrl?: string) => request<{ title?: string; content: string }>('/api/books/content', { method: 'POST', body: JSON.stringify({ sourceId, chapterUrl, bookUrl }) }),
  progress: (sourceId: string, bookUrl: string) => request<ReadingProgress | undefined>(`/api/reading-progress?sourceId=${encodeURIComponent(sourceId)}&bookUrl=${encodeURIComponent(bookUrl)}`),
  saveProgress: (sourceId: string, bookUrl: string, chapterUrl: string, chapterIndex: number, scrollPosition: number) => request<ReadingProgress>('/api/reading-progress', { method: 'PUT', body: JSON.stringify({ sourceId, bookUrl, chapterUrl, chapterIndex, scrollPosition }) }),
  bookshelf: () => request<BookshelfItem[]>('/api/bookshelf'),
  addToBookshelf: (book: BookshelfWrite) => request<BookshelfItem>('/api/bookshelf', { method: 'POST', body: JSON.stringify(book) }),
  removeFromBookshelf: (sourceId: string, bookUrl: string) => request<void>(`/api/bookshelf?sourceId=${encodeURIComponent(sourceId)}&bookUrl=${encodeURIComponent(bookUrl)}`, { method: 'DELETE' }),
  cacheBookshelfBook: (sourceId: string, bookUrl: string) => request<{ status: string }>('/api/bookshelf/cache', { method: 'POST', body: JSON.stringify({ sourceId, bookUrl }) }),
  cancelBookCache: (sourceId: string, bookUrl: string) => request<void>(`/api/bookshelf/cache?sourceId=${encodeURIComponent(sourceId)}&bookUrl=${encodeURIComponent(bookUrl)}`, { method: 'DELETE' }),
  setBookshelfCompleted: (sourceId: string, bookUrl: string, completed: boolean) => request<BookshelfItem>('/api/bookshelf/status', { method: 'PUT', body: JSON.stringify({ sourceId, bookUrl, completed }) }),
  switchBookshelfSource: (value: BookshelfSourceSwitch) => request<BookshelfItem>('/api/bookshelf/switch-source', { method: 'POST', body: JSON.stringify(value) }),
  cover: (key: string) => `/api/covers/${encodeURIComponent(key)}`,
}

export function streamSearch(keyword: string, sourceIds: string[] | undefined, onEvent: (event: SearchStreamEvent) => void, onError: (message: string) => void, onClose: () => void): WebSocket {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:'
  const socket = new WebSocket(`${protocol}//${location.host}/api/search/stream?csrf=${encodeURIComponent(csrfToken ?? '')}`)
  let reported = false
  socket.addEventListener('open', () => queueMicrotask(() => {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify({ keyword, sourceIds }))
  }))
  socket.addEventListener('message', event => {
    try { onEvent(JSON.parse(event.data) as SearchStreamEvent) }
    catch { reported = true; onError('搜索响应格式无效') }
  })
  socket.addEventListener('error', () => { if (!reported) { reported = true; onError('搜索连接中断，请重试') } })
  socket.addEventListener('close', () => { if (!reported) onClose() })
  return socket
}

import { useEffect, useState } from 'react'
import { Icon } from './icons'

export type ToastType = 'success' | 'info' | 'error' | 'warning'

export type ToastItem = {
  id: string
  type: ToastType
  message: string
  duration?: number
}

type ToastListener = (toasts: ToastItem[]) => void

class ToastStore {
  private toasts: ToastItem[] = []
  private listeners = new Set<ToastListener>()

  subscribe(listener: ToastListener) {
    this.listeners.add(listener)
    listener(this.toasts)
    return () => {
      this.listeners.delete(listener)
    }
  }

  private notify() {
    this.listeners.forEach(listener => listener([...this.toasts]))
  }

  show(message: string, type: ToastType = 'info', duration = 2800) {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
    const toast: ToastItem = { id, message, type, duration }
    this.toasts = [...this.toasts, toast]
    this.notify()

    if (duration > 0) {
      setTimeout(() => {
        this.dismiss(id)
      }, duration)
    }
    return id
  }

  dismiss(id: string) {
    this.toasts = this.toasts.filter(t => t.id !== id)
    this.notify()
  }

  success(message: string, duration = 2800) {
    return this.show(message, 'success', duration)
  }

  info(message: string, duration = 2800) {
    return this.show(message, 'info', duration)
  }

  error(message: string, duration = 3500) {
    return this.show(message, 'error', duration)
  }

  warning(message: string, duration = 3000) {
    return this.show(message, 'warning', duration)
  }
}

export const toast = new ToastStore()

export function ToastContainer() {
  const [toasts, setToasts] = useState<ToastItem[]>([])

  useEffect(() => {
    return toast.subscribe(setToasts)
  }, [])

  if (toasts.length === 0) return null

  return (
    <div className="toast-container" aria-live="polite" role="region">
      {toasts.map(item => {
        const iconName = item.type === 'success' ? 'check'
          : item.type === 'error' ? 'close'
          : item.type === 'warning' ? 'sliders'
          : 'book'

        return (
          <div key={item.id} className={`toast-item toast-${item.type}`} role="status">
            <span className="toast-icon">
              <Icon name={iconName} />
            </span>
            <span className="toast-message">{item.message}</span>
            <button
              className="toast-close"
              onClick={() => toast.dismiss(item.id)}
              aria-label="关闭提示"
            >
              <Icon name="close" />
            </button>
          </div>
        )
      })}
    </div>
  )
}

import test from 'node:test'
